INSERT IGNORE INTO categories (slug, sort_order, category_json) VALUES
('love', 0, '{"slug":"love","name":"Love","prompt":"For the ones who feel like home.","description":"Celebrate the little things, say what you admire, or put a lifetime of affection into a single note.","styles":"Soft rose, hand-drawn botanicals and an envelope reveal."}'),
('anger', 1, '{"slug":"anger","name":"Anger","prompt":"Say the hard things with care.","description":"Make room for frustration and hurt. Use this space to say what happened, how it felt, and what you need going forward.","styles":"Burgundy ink, graphic lines and a deliberate paper reveal."}'),
('sadness', 2, '{"slug":"sadness","name":"Sadness","prompt":"A little space for heavy days.","description":"Reach across the quiet with a gentle message about what you miss, what hurts, or how much someone means to you.","styles":"Moonlight, rain and a soft blue palette."}'),
('apology', 3, '{"slug":"apology","name":"Apology","prompt":"Find the words to begin again.","description":"Own the hurt, offer a sincere apology and give the other person room to respond in their own time.","styles":"Warm paper, sage leaves and a gentle unfolding motion."}'),
('secret-crush', 4, '{"slug":"secret-crush","name":"Secret Crush","prompt":"For what’s still unsaid.","description":"Give a quiet admiration a little room to flutter, with something light, kind and unexpected.","styles":"Lilac, hand-drawn butterflies and little points of starlight."}');
INSERT IGNORE INTO templates (slug, category_slug, sort_order, status, version, metadata_json, document_json) VALUES
('eternal-love', 'love', 0, 'published', 1, '{"name":"Eternal Love","style":"Romantic","tier":"free","ink":"#743b4c","paper":"#f7e7e5","decoration":"botanical","openingAnimation":"envelope","backgroundEffect":"hearts","label":"A LITTLE LOVE LETTER","cover":"Eternal Love","heading":"The little things","message":"The way you laugh before the joke is over. The tea you leave at my desk. The way a whole day feels softer when you’re in it. I love all of it, and I love you.","signature":"With all my love","id":"eternal-love","tags":["love","romantic"]}', '{"schemaVersion":1,"canvas":{"width":1080,"height":1350,"background":{"type":"color","value":"#f7e7e5"}},"elements":[{"id":"ornament","type":"decoration","asset":"botanical","x":405,"y":116,"width":270,"height":270,"rotation":0,"opacity":1,"locked":false,"visible":true},{"id":"heading","type":"text","content":"The little things","x":110,"y":408,"width":860,"fontSize":104,"fontFamily":"Playfair Display","fill":"#743b4c","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":0}},{"id":"message","type":"text","content":"The way you laugh before the joke is over. The tea you leave at my desk. The way a whole day feels softer when you’re in it. I love all of it, and I love you.","x":110,"y":713,"width":860,"fontSize":45,"fontFamily":"Inter","fill":"#743b4c","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":0}},{"id":"signature","type":"text","content":"With all my love","x":110,"y":1110,"width":860,"fontSize":60,"fontFamily":"Playfair Display","fill":"#743b4c","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":180}}],"experience":{"openingAnimation":"envelope","backgroundEffect":"hearts","music":null}}'),
('unspoken-words', 'anger', 1, 'published', 1, '{"name":"Unspoken Words","style":"Editorial","tier":"free","ink":"#fff1e8","paper":"#623046","decoration":"lines","openingAnimation":"unfold","backgroundEffect":"embers","label":"WORDS I’VE HELD ON TO","cover":"Unspoken Words","heading":"Can we talk?","message":"I felt hurt when our plans changed and I only found out later. I’d like us to talk about what happened, and I need a little more notice next time.","signature":"When you’re ready to talk","id":"unspoken-words","tags":["anger","editorial"]}', '{"schemaVersion":1,"canvas":{"width":1080,"height":1350,"background":{"type":"color","value":"#623046"}},"elements":[{"id":"ornament","type":"decoration","asset":"lines","x":405,"y":116,"width":270,"height":270,"rotation":0,"opacity":1,"locked":false,"visible":true},{"id":"heading","type":"text","content":"Can we talk?","x":110,"y":408,"width":860,"fontSize":104,"fontFamily":"Playfair Display","fill":"#fff1e8","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":0}},{"id":"message","type":"text","content":"I felt hurt when our plans changed and I only found out later. I’d like us to talk about what happened, and I need a little more notice next time.","x":110,"y":713,"width":860,"fontSize":45,"fontFamily":"Inter","fill":"#fff1e8","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":0}},{"id":"signature","type":"text","content":"When you’re ready to talk","x":110,"y":1110,"width":860,"fontSize":60,"fontFamily":"Playfair Display","fill":"#fff1e8","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":180}}],"experience":{"openingAnimation":"unfold","backgroundEffect":"embers","music":null}}'),
('silent-tears', 'sadness', 2, 'published', 1, '{"name":"Silent Tears","style":"Atmospheric","tier":"free","ink":"#334d63","paper":"#dce9f3","decoration":"moon","openingAnimation":"fade","backgroundEffect":"rain","label":"UNDER THE SAME SKY","cover":"Silent Tears","heading":"I miss you today","message":"Some days it’s the smallest things that remind me of you. The rain against the windows did it this morning. I wanted you to know I was thinking of you.","signature":"From across the miles","id":"silent-tears","tags":["sadness","atmospheric"]}', '{"schemaVersion":1,"canvas":{"width":1080,"height":1350,"background":{"type":"color","value":"#dce9f3"}},"elements":[{"id":"ornament","type":"decoration","asset":"moon","x":405,"y":116,"width":270,"height":270,"rotation":0,"opacity":1,"locked":false,"visible":true},{"id":"heading","type":"text","content":"I miss you today","x":110,"y":408,"width":860,"fontSize":104,"fontFamily":"Playfair Display","fill":"#334d63","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":0}},{"id":"message","type":"text","content":"Some days it’s the smallest things that remind me of you. The rain against the windows did it this morning. I wanted you to know I was thinking of you.","x":110,"y":713,"width":860,"fontSize":45,"fontFamily":"Inter","fill":"#334d63","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":0}},{"id":"signature","type":"text","content":"From across the miles","x":110,"y":1110,"width":860,"fontSize":60,"fontFamily":"Playfair Display","fill":"#334d63","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":180}}],"experience":{"openingAnimation":"fade","backgroundEffect":"rain","music":null}}'),
('truly-sorry', 'apology', 3, 'published', 1, '{"name":"I’m Truly Sorry","style":"Botanical","tier":"premium","ink":"#385042","paper":"#e5eadb","decoration":"sage","openingAnimation":"unfold","backgroundEffect":"petals","label":"AN OFFERING OF PEACE","cover":"I’m Truly Sorry","heading":"I owe you an apology","message":"I spoke before I listened, and what I said hurt you. I’m sorry. I’ll give you the space you need, and when you’re ready, I’d like to hear how this felt for you.","signature":"With love and care","id":"truly-sorry","tags":["apology","botanical"]}', '{"schemaVersion":1,"canvas":{"width":1080,"height":1350,"background":{"type":"color","value":"#e5eadb"}},"elements":[{"id":"ornament","type":"decoration","asset":"sage","x":405,"y":116,"width":270,"height":270,"rotation":0,"opacity":1,"locked":false,"visible":true},{"id":"heading","type":"text","content":"I owe you an apology","x":110,"y":408,"width":860,"fontSize":104,"fontFamily":"Playfair Display","fill":"#385042","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":0}},{"id":"message","type":"text","content":"I spoke before I listened, and what I said hurt you. I’m sorry. I’ll give you the space you need, and when you’re ready, I’d like to hear how this felt for you.","x":110,"y":713,"width":860,"fontSize":45,"fontFamily":"Inter","fill":"#385042","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":0}},{"id":"signature","type":"text","content":"With love and care","x":110,"y":1110,"width":860,"fontSize":60,"fontFamily":"Playfair Display","fill":"#385042","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":180}}],"experience":{"openingAnimation":"unfold","backgroundEffect":"petals","music":null}}'),
('secret-admirer', 'secret-crush', 4, 'published', 1, '{"name":"Secret Admirer","style":"Whimsical","tier":"premium","ink":"#5b4373","paper":"#eae0f4","decoration":"butterfly","openingAnimation":"envelope","backgroundEffect":"stars","label":"A SMALL CONFESSION","cover":"Secret Admirer","heading":"You make me smile","message":"You have a way of making an ordinary room a little brighter. I thought you should know someone notices. I hope today gives you as many reasons to smile as you give me.","signature":"","id":"secret-admirer","tags":["secret-crush","whimsical"]}', '{"schemaVersion":1,"canvas":{"width":1080,"height":1350,"background":{"type":"color","value":"#eae0f4"}},"elements":[{"id":"ornament","type":"decoration","asset":"butterfly","x":405,"y":116,"width":270,"height":270,"rotation":0,"opacity":1,"locked":false,"visible":true},{"id":"heading","type":"text","content":"You make me smile","x":110,"y":408,"width":860,"fontSize":104,"fontFamily":"Playfair Display","fill":"#5b4373","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":0}},{"id":"message","type":"text","content":"You have a way of making an ordinary room a little brighter. I thought you should know someone notices. I hope today gives you as many reasons to smile as you give me.","x":110,"y":713,"width":860,"fontSize":45,"fontFamily":"Inter","fill":"#5b4373","rotation":0,"opacity":1,"locked":false,"visible":true,"align":"center","animation":{"type":"fade-in","duration":520,"delay":0}}],"experience":{"openingAnimation":"envelope","backgroundEffect":"stars","music":null}}');
